<?php
require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/csrf.php'; require_once __DIR__ . '/includes/functions.php';
$pdo = getDbConnection(); $error = null;
if (empty($_SESSION['password_reset_user_id']) || empty($_SESSION['password_reset_verified']) || ($_SESSION['password_reset_expires'] ?? 0) < time()) { header('Location: ' . baseUrl('forgot-password.php')); exit; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') { enforceCsrf(); $password = $_POST['new_password'] ?? ''; $confirm = $_POST['confirm_password'] ?? ''; if (strlen($password) < 8 || $password !== $confirm) $error = 'Passwords must match and be at least 8 characters.'; else { $stmt = $pdo->prepare('UPDATE users SET password_hash = :hash WHERE user_id = :uid'); $stmt->execute([':hash' => password_hash($password, PASSWORD_DEFAULT), ':uid' => $_SESSION['password_reset_user_id']]); $pdo->prepare("UPDATE otp_verifications SET is_used = 1 WHERE otp_id = :oid AND purpose = 'password_reset'")->execute([':oid' => $_SESSION['password_reset_otp_id']]); unset($_SESSION['password_reset_user_id'], $_SESSION['password_reset_otp_id'], $_SESSION['password_reset_expires'], $_SESSION['password_reset_verified']); session_regenerate_id(true); setFlash('success', 'Password reset successfully. Please log in.'); header('Location: ' . baseUrl('login.php')); exit; } }
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Reset Password - IMD Portal</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="<?= baseUrl('assets/css/imd-auth.css') ?>"></head><body class="bg-light d-flex flex-column min-vh-100"><header class="portal-header"><div class="container"><a href="<?= baseUrl() ?>" class="portal-brand fs-4">IMD Training Division Portal</a><div class="gov-emblem-text">India Meteorological Department | Govt. of India</div></div></header><main class="container my-auto py-5"><div class="row justify-content-center"><div class="col-md-6 col-lg-5"><div class="card card-auth p-4"><div class="card-body"><div class="text-center mb-4"><h3 class="card-title text-imd-navy fw-bold">Reset Password</h3><p class="text-muted small">Create a new password for your account.</p></div><?php if ($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?><form method="post"><?= csrfField() ?><div class="mb-3"><label for="new_password" class="form-label">New Password</label><input type="password" class="form-control" id="new_password" name="new_password" minlength="8" required></div><div class="mb-4"><label for="confirm_password" class="form-label">Confirm New Password</label><input type="password" class="form-control" id="confirm_password" name="confirm_password" minlength="8" required></div><button type="submit" class="btn btn-imd w-100 py-2 fs-5">Reset Password</button></form><div class="text-center mt-4"><a href="<?= baseUrl('login.php') ?>" class="text-imd-navy fw-bold text-decoration-none">Back to Login</a></div></div></div></div></div></main><footer class="text-center py-3 mt-auto"><small>&copy; <?= date('Y') ?> India Meteorological Department. Training Division Portal.</small></footer></body></html>
